import jSwiper from '@/component/jSwiper.vue';
import config from '@/common/config.js';
export default {
	data() {
		return {
			userData: {},

			currentTab: 0,

			tabList: [{ id: 0, name: '主页' }, { id: 1, name: '动态' }],

			photos: [],

			greetings: '', // 问候据

			isShowDialog: false, // 是否显示修改密码弹窗

			isShowUploadAvatar: false // 是否显示大头像弹窗
		};
	},

	onLoad() {
		this.getUserInfo();
	},

	onShow() {
		this.createGreetings();
		
	},

	methods: {
		// 获取问候据
		createGreetings() {
			const hours = new Date().getHours(),
				greetSuffix = '好~';
			let greetPrefix = '';
			if (hours >= 0 && hours < 6) {
				greetPrefix = '晚上';
			}
			if (hours >= 6 && hours < 11) {
				greetPrefix = '上午';
			}
			if (hours >= 11 && hours <= 12) {
				greetPrefix = '中午';
			}
			if (hours > 12 && hours <= 18) {
				greetPrefix = '下午';
			}
			if (hours > 18 && hours <= 23) {
				greetPrefix = '晚上';
			}
			this.greetings = greetPrefix + greetSuffix;
		},

		// 打开/关闭上传头像弹窗
		actionUploadAvatar(b) {
			this.isShowUploadAvatar = b;
		},

		// 上传头像
		changeAvatar() {
			const _self = this;
			uni.chooseImage({
				success: res => {
					const tempFilePaths = res.tempFilePaths;
					uni.uploadFile({
						url: `${config.getConfig().baseUrl}/user/uploadAvatar`,
						filePath: tempFilePaths[0],
						name: 'avatarFile',
						header: {
							Authorization: _self.$store.state.token
						},
						success: data => {
							const parseData = JSON.parse(data.data);
							_self.actionUploadAvatar(false);
							_self.userData.avatar = parseData.data.avatar;
						},
						fail: e => {
							_self.$common.showModal(e.msg || '');
						}
					});
				}
			});
		},

		//是否开启首页动画
		isOpenIndexAniEvt() {
			const b = this.$store.state.isOpenIndexAni;
			this.$store.commit('SETINDEXANI', !b);
		},

		// 滑动swiper
		swiperChange(e) {
			this.currentTab = e;
		},
		// 点击tab
		changeTab(id) {
			this.currentTab = id;
		},

		// 查询用户信息
		getUserInfo() {
			this.$api({
				url: '/user/info'
			})
				.then(res => {
					if (res) {
						this.userData = res;
					}
				})
				.catch(e => {
					this.$common.showModal(e.msg || '');
				})
				.finally(() => {});
		}
	},
	components: { jSwiper }
};
